"use client";
import React, { useEffect, useState } from "react";
import {
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage
} from "@/components/ui/form";
import {
  Command,
  CommandList,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem
} from "@/components/ui/command";
// Replaced Radix Popover (trigger caused React 19 element.ref warning) with headless popover logic
import { ChevronsUpDown } from "lucide-react";
import { buttonVariants } from "@/components/ui/button";
import { cn } from "@/lib/utils";

interface Country {
    name: string;
    dialCode: string;
    code: string;
}

interface SelectDialCodeProps {
    form: any;
    fieldName: string;
    fieldLabel: string;
    initialDialCode?: any;
}

const SelectDialCode = ({ form, fieldName, fieldLabel, initialDialCode }: SelectDialCodeProps) => {
  const [countryList, setCountryList] = useState<Country[]>([]);
  const [selectedCountry, setSelectedCountry] = useState<Country | undefined>(undefined);
  const [isPopoverOpen, setIsPopoverOpen] = useState(false);
  const triggerRef = React.useRef<HTMLButtonElement | null>(null);
  const panelRef = React.useRef<HTMLDivElement | null>(null);
  const [isClient, setIsClient] = useState(false);

  useEffect(() => {
    setIsClient(true);
    if (typeof window !== "undefined") {
      import("country-list-with-dial-code-and-flag").then(module => {
        const CountryList = module.default || module;
        if (typeof CountryList.getAll === "function") {
          const _country = CountryList.getAll();
          setCountryList(_country);
          if (initialDialCode) {
            const defaultCountry = _country.find(country => country.dialCode === initialDialCode);
            if (defaultCountry) {
              setSelectedCountry(defaultCountry);
              form.setValue(fieldName, defaultCountry.dialCode);
            }
          }
        }
      });
    }
  }, [initialDialCode, form, fieldName]);

  const onSelectCountry = (value: string) => {
    const _country = countryList.at(Number(value));
    if (_country) {
      setSelectedCountry(_country);
      setIsPopoverOpen(false);
      form.setValue(fieldName, _country.dialCode);
    }
  };

  // close on outside click / escape (must always declare hook to keep order stable)
  useEffect(() => {
    if (!isClient || !isPopoverOpen) return;
    function onKey(e: KeyboardEvent) {
      if (e.key === "Escape") setIsPopoverOpen(false);
    }
    function onClick(e: MouseEvent) {
      const t = e.target as Node;
      if (panelRef.current?.contains(t) || triggerRef.current?.contains(t)) return;
      setIsPopoverOpen(false);
    }
    window.addEventListener("keydown", onKey);
    window.addEventListener("mousedown", onClick);
    return () => {
      window.removeEventListener("keydown", onKey);
      window.removeEventListener("mousedown", onClick);
    };
  }, [isClient, isPopoverOpen]);

  if (!isClient) {
    return null; // Defer rendering until client hydration to avoid mismatch
  }

  return (
    <div>
      <FormField
        control={form.control}
        name={fieldName}
        render={() => (
          <FormItem>
            <FormLabel>{fieldLabel}</FormLabel>
            <FormControl>
              <div className="relative">
                <button
                  type="button"
                  ref={triggerRef}
                  onClick={() => setIsPopoverOpen(o => !o)}
                  role="combobox"
                  aria-expanded={isPopoverOpen}
                  aria-haspopup="listbox"
                  className={cn(
                    buttonVariants({ variant: "outline" }),
                    "w-full flex justify-between space-x-1 truncate"
                  )}
                >
                  {selectedCountry ? selectedCountry.dialCode : "Dial Code"}
                  <ChevronsUpDown className="h-4 w-4 shrink-0 opacity-50" />
                </button>
                {isPopoverOpen && (
                  <div
                    ref={panelRef}
                    role="listbox"
                    aria-label="Dial codes"
                    className="absolute z-50 mt-2 w-[300px] rounded-md border bg-popover p-1 text-popover-foreground shadow-md focus:outline-none"
                  >
                    <Command
                      filter={(value, search) => {
                        const _country = countryList.at(Number(value));
                        if (!_country) return 0;
                        const q = String(search ?? "").trim().toLowerCase();
                        if (!q) return 1;
                        const normalizedQ = q.replace(/\+/g, "");
                        const dial = String(_country.dialCode ?? "").toLowerCase().replace(/\+/g, "");
                        const name = String(_country.name ?? "").toLowerCase();
                        if (dial.includes(normalizedQ) || name.includes(normalizedQ) || name.includes(q)) {
                          return 1;
                        }
                        return 0;
                      }}
                    >
                      <CommandInput placeholder="Search by dial code or country" />
                      <CommandList>
                        <CommandEmpty>No dial code found.</CommandEmpty>
                        <CommandGroup>
                          {countryList.map((country, index) => (
                            <CommandItem
                              key={index}
                              onSelect={() => onSelectCountry(index.toString())}
                              value={index.toString()}
                            >
                              <div className="w-full flex items-center justify-between">
                                <p>{country.dialCode}</p> <p>{country.name}</p>
                              </div>
                            </CommandItem>
                          ))}
                        </CommandGroup>
                      </CommandList>
                    </Command>
                  </div>
                )}
              </div>
            </FormControl>
            <FormMessage />
          </FormItem>
        )}
      />
    </div>
  );
};

export default SelectDialCode;

"use client";

import React, { useState } from "react";
import Link from "next/link";
import { usePathname } from "next/navigation";
import pathUrls from "@/data/pathUrl.json";
import IconController from "../icon-controller";
import { CreditCard } from "lucide-react";
import Image from "next/image";
import useMediaQuery from "@/hooks/useMediaQuery";
import { ThemeToggle } from "../theme-toggle";
import UserAvatar from "../user-avatar";

const linksStyle =
  "flex items-center gap-3 rounded-lg px-3 py-2 text-gray-500 transition-all hover:text-gray-900 dark:text-gray-400 dark:hover:text-gray-50";
const selectedLinkStyle =
  "flex items-center gap-3 rounded-lg bg-gray-200 px-3 py-2 text-gray-900  transition-all hover:text-gray-900 dark:bg-gray-800 dark:text-gray-50";

const DashboardNavBar: React.FC = () => {
  const pathname = usePathname();
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const isDesktop = useMediaQuery("(min-width: 1024px)");

  const toggleMobileMenu = () => {
    setMobileMenuOpen(!mobileMenuOpen);
  };

  return (
    <div className={`border-b-2 bg-gray-100/40 lg:border-r lg:bg-gray-100/40 dark:bg-gray-800/40 ${isDesktop ? "lg:block h-full" : "lg:hidden h-fit"}`}>
      <div className={`flex justify-between items-center px-6 h-[60px] ${isDesktop ? "lg:hidden" : "lg:block"}`}>

        {isDesktop ? (
          <nav className="grid items-start px-4 text-sm font-medium">
            <Link
              className="flex items-center gap-2 font-semibold"
              href={pathUrls.dashboard.linkHref}
            >
              <Image src={"/kenlogo.png"} alt="logo" width={33} height={25} />
              <span className="">Users app</span>
            </Link>
            <Link
              className={
                pathname === pathUrls.dashboard.linkHref
                  ? selectedLinkStyle
                  : linksStyle
              }
              href={pathUrls.dashboard.linkHref}
            >
              <IconController icon="home" />
              {pathUrls.dashboard.linkText}sssss
            </Link>

            <Link
              className={
                pathname === pathUrls.settings.linkHref
                  ? selectedLinkStyle
                  : linksStyle
              }
              href={pathUrls.settings.linkHref}
            >
              <IconController icon="settings" />
              {pathUrls.settings.linkText}
            </Link>
          </nav>
        ) : (
          <div className="flex place-content-between w-full">
            <button
              className="text-gray-500 dark:text-gray-400"
              onClick={toggleMobileMenu}
            >
              {mobileMenuOpen ? (
                <IconController icon="X" />
              ) : (
                <IconController icon="menu" />
              )}
            </button>
            <div className="flex items-center space-x-2">
              {/* <BitcoinPrice /> */}
              <ThemeToggle />
              <UserAvatar />
            </div>
          </div>
        )}
      </div>
      {isDesktop && (
        <nav className="px-4 py-2 text-sm font-medium">
          <div className="flex h-[60px] items-center px-6">
            <Link
              className="flex items-center gap-2"
              href={pathUrls.dashboard.linkHref}
            >
              <Image src={"/kenlogo.png"} alt="logo" width={33} height={25} />
              <span className="text-base">Vendors Portal</span>
            </Link>
          </div>
          <Link
            className={
              pathname === pathUrls.dashboard.linkHref
                ? selectedLinkStyle
                : linksStyle
            }
            href={pathUrls.dashboard.linkHref}
          >
            <IconController icon="home" />
            {pathUrls.dashboard.linkText}
          </Link>
          <Link
            className={
              pathname === pathUrls.settings.linkHref
                ? selectedLinkStyle
                : linksStyle
            }
            href={pathUrls.settings.linkHref}
          >
            <IconController icon="settings" />
            {pathUrls.settings.linkText}
          </Link>
        </nav>
      )}
      {!isDesktop && mobileMenuOpen && (
        <nav className="px-4 py-2 bg-gray-100 dark:bg-gray-800/40 text-sm font-semibold">
          <Link
            onClick={() => setMobileMenuOpen(false)}
            className={
              pathname === pathUrls.dashboard.linkHref
                ? selectedLinkStyle
                : linksStyle
            }
            href={pathUrls.dashboard.linkHref}
          >
            <IconController icon="home" />
            {pathUrls.dashboard.linkText}
          </Link>
          <Link
            onClick={() => setMobileMenuOpen(false)}
            className={
              pathname === pathUrls.settings.linkHref
                ? selectedLinkStyle
                : linksStyle
            }
            href={pathUrls.settings.linkHref}
          >
            <IconController icon="settings" />
            {pathUrls.settings.linkText}
          </Link>
        </nav>
      )}
    </div>
  );
};

export default DashboardNavBar;

"use client";

import * as React from "react";
import * as PopoverPrimitive from "@radix-ui/react-popover";

import { cn } from "@/lib/utils";

const Popover = PopoverPrimitive.Root;

// Use Radix primitive directly (was wrapped before; revert to reduce surface of React 19 warnings)
const PopoverTrigger = PopoverPrimitive.Trigger;

const PopoverContent = React.forwardRef<
  HTMLButtonElement,
  React.ComponentPropsWithoutRef<typeof PopoverPrimitive.Content>
>(({ className, align = "center", sideOffset = 4, ...props }, ref) => (
  <PopoverPrimitive.Portal>
    <PopoverPrimitive.Content

      align={align}
      sideOffset={sideOffset}
      className={cn(
        "z-50 w-72 rounded-md border bg-popover p-4 text-popover-foreground shadow-md outline-none data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2",
        className
      )}
      {...props}
    />
  </PopoverPrimitive.Portal>
));
PopoverContent.displayName = PopoverPrimitive.Content.displayName;

export { Popover, PopoverTrigger, PopoverContent };
